        "text": "**Visa needed for tourism:** No, if you stay 30 days or less. **Maximum stay:** 30 days per entry. **Started:** 15 September 2026, replacing the 60-day exemption. **Extension:** Up to 30 days, at the Immigration Bureau's discretion. **TDAC:** Free, compulsory, submit within 3 days before arrival. **Carry:** Hotel booking, onward ticket within 30 days, funds of about 20,000 baht per person. **Longer stays:** Tourist visa (60 days) or DTV (180 days per entry) via thaievisa.go.th."
