        "text": "On 22 October 2026 the Chinese Embassy in India published a notice saying that from 26 October the Embassy and the Consulate General in Mumbai will directly accept and process applications for Chinese visas and consular legalisation. Services for the Kolkata consular district are temporarily handled by the Embassy in New Delhi. The Embassy published an updated visa application notice and a new schedule of consular fees on the same day."
