        "type": "p",
        "text": "Travel trade reports add details we could not find on the Embassy's own pages. They say the service centres stop taking new applications from 26 October, and processed passports can be collected from them until **12 noon on 30 October 2026**. They also say online applications submitted after 5 pm on 23 October carry no centre service fee, and service fees already paid are not refunded."
