        "text": "Visa hours, Monday to Friday except public holidays: the **New Delhi Embassy** takes applications from 9 am to 12 noon and returns passports from 3 pm to 5:30 pm. The **Mumbai Consulate** takes applications from 2:30 pm to 5:30 pm and returns passports from 10 am to 12:30 pm. Check each office's holiday list before you go."
