        "type": "p",
        "text": "You need **six months of personal bank statements** showing an average monthly balance of at least **₹1 lakh**. Instead of statements, you can give a bank deposit certificate for a similar amount, issued at least 3 months before you apply and signed and stamped by the bank. The Embassy notice has a full checklist for each visa type. Read it for your category before you upload anything."
