        "type": "p",
        "text": "The fee schedule says the Chinese Embassy and Consulates in India **only accept demand drafts**, and that cash, personal cheques and other methods are temporarily not accepted. The draft must be printed by a bank in India. Handwritten or incomplete drafts are not accepted. Make it payable to **CHINESE EMBASSY, NEW DELHI** or **CONSULATE GENERAL OF THE PEOPLE'S REPUBLIC OF CHINA IN MUMBAI**. On the back, write your full name, pick-up slip number and phone number. Fees are paid at collection, and you get the pick-up slip only when you submit, so in practice the draft is made between the two visits."
