        "type": "p",
        "text": "Regular processing takes **7 working days** and express takes **4 working days**, counted from the day after you submit your passport. The fee schedule also lists urgent processing in 2 working days where applicable. Before that, your online form has to pass review. Plan for at least two to three weeks in total."
